def _ficha(imovel: dict | None) -> dict:
    """A ficha que o modelo lê: a página pública do imóvel, sem fotos nem a observação interna."""
    i = dict(imovel or {})
    for k in ("fotos", "obs", "geo", "slug", "pode_enviar", "parceiro", "link"):
        i.pop(k, None)
    return i

