def _quem(m: dict) -> str:
    if m.get("de") == "comprador":
        return "CLIENTE"
    if m.get("de") == "sistema":
        return "SISTEMA DA OLX"
    por = (m.get("por") or "").strip()
    return "NAY" if por.lower().startswith("nay") else "EQUIPE"

