                            modelo.chamar) if ctx else None
            print(json.dumps(d.__dict__ if d else None, ensure_ascii=False, indent=2))
        elif comando == "responder":
            print("enviada:", responder(conn, int(argv[1]), argv[2], argv[3] if len(argv) > 3 else None))
        elif comando == "gente":
