def _dela(turno: str) -> str:
    """O que a pessoa escreveu (as linhas CLIENTE: do turno): a palavra que ELA usou a Nay pode usar de volta."""
    return "\n".join(l for l in (turno or "").split("\n") if l.startswith("CLIENTE:"))

